def transform(grid):
    if not grid or not grid[0]:
        return grid

    h, w = len(grid), len(grid[0])
    new_h, new_w = h * 3, w * 3
    result = [[0] * new_w for _ in range(new_h)]

    for i in range(h):
        for j in range(w):
            val = grid[i][j]
            if val == 0:
                continue

            mod = val % 3

            if mod == 0:
                # 6 pattern: [[v,v,0],[v,0,v],[0,v,v]]
                for di in range(3):
                    for dj in range(3):
                        if (di == 0 and dj in [0, 1]) or \
                           (di == 1 and dj in [0, 2]) or \
                           (di == 2 and dj in [1, 2]):
                            result[i*3 + di][j*3 + dj] = val
                        else:
                            result[i*3 + di][j*3 + dj] = 0
            elif mod == 1:
                # 7 pattern: [[v,0,v],[0,0,0],[v,0,v]]
                for di in range(3):
                    for dj in range(3):
                        if (di == 0 and dj in [0, 2]) or (di == 2 and dj in [0, 2]):
                            result[i*3 + di][j*3 + dj] = val
                        else:
                            result[i*3 + di][j*3 + dj] = 0
            elif mod == 2:
                # Need a third pattern...
                for di in range(3):
                    for dj in range(3):
                        result[i*3 + di][j*3 + dj] = 0

    return result

